import express from 'express';
import { AskRequest } from '../shared/contracts';
import { retrieve } from './retrieval';
import { answer } from './ai';
const router = express.Router();
router.post('/ask-book', async function askBook(req, res) { const passages = retrieve(req.body as AskRequest); try { res.json(await answer(passages)); } catch { res.json({ answer: passages }); } });
export default router;

